VALUES (649, '0', $t$ASK 649: the engine manual says the dashboard function lists the 12 debaters the live list holds$t$,
  $t$Engine manual part 11.0, in the ASK 482 entry, said dash_debaters "lists the 11 debaters (claude, chatgpt, gemini, grok, mimo, haiku, opus, glm, qwen4max, spark, sol62)" and "the two drop-downs list the 11 debaters". The live function holds 12 rows: claude, chatgpt, gemini, grok, mimo, opus, glm, qwen4max, spark, sol62, hydrogen, neon; haiku is not in it (W3's SQL, Wall 12055; W1, Wall 12056). Change, in part 11.0 only: the first phrase names the 12; the second reads "the two drop-downs list the debaters `dash_debaters()` gives". Expected effect: the manual states what the live function holds. No engine or database behaviour is changed.$t$,
  'yes',
  $t$Written by W3 on the operator's press "Write it" (08:23 CST 2026-11-25) on W3's card: engine manual part 11.0, version 326 (db2c50ca60851ad3db8fbadef563652f, 37,390 characters) to version 327 (a631296d6a85652ca539ed74282a6850, 37,420), two literal replacements, each old text found once; engine_manual_log row 347; audit 42225 (Wall 12073). NEW BASE: W1 graded the two pairs as a preview on version 318 (result 38,138 characters, md5 81093c11dc5c0809a4d1dfacaa586c7f; Wall 12056, "whichever is written second is previewed again"). ASK 648 was written first, so the same two pairs were previewed again inside the write call on version 326 and written on that md5 (37,390 plus 30). W1 read it back PASS and computed that version 327 equals version 326 with the two graded pairs applied (Wall 12074). YES, because the objective is the manual text itself and it is written and read back; no run is needed to show it. Changed: two phrases. Deleted: nothing else; the name haiku left the list. NOT CHECKED by W3 or W1: the dashboard page itself; the second phrase rests on the entry's own statement that the page reads the list through the dashboard function.$t$,
  '12055, 12056, 12073, 12074',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$No words of the operator on this defect were read by W3. The defect was seen by W3 while drafting ASK 648 (Wall 12054, item 6) and numbered by the coordinator. W3's write card (cmsg_017ZQamDMHrS6fqMHnQDVo5859JzQhfwXW93pcDSvdwcWr, "Write the ASK 649 correction (the dashboard lists 12 debaters) into the engine manual?"): he pressed "Write it" at 08:23 CST 2026-11-25.$t$::text),
  $j${"answer": "Write it", "question": "Write the ASK 649 correction (the dashboard lists 12 debaters) into the engine manual?", "options": {"Write it": "I change the two sentences shown above in part 11.0: 11 debaters with haiku becomes the 12 the live list holds. W1 reads it back.", "Hold": "The manual keeps saying 11 debaters and still names haiku, which the live list does not hold."}, "thread": "W3", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo5859JzQhfwXW93pcDSvdwcWr", "press_time": "08:23 CST 2026-11-25", "source": "W3's own card, re-read by W3, and the press delivered to W3's thread."}$j$::jsonb,
  'W3',
  $j${"md5": "1a2e03af69f6a5dfee80be6fda3be3ef", "path": "manual1123/w3/a649/em_pairs_649_draft1.json", "note": "no separate plan file: the two pairs are the plan and the change.", "source": "md5sum by W3"}$j$::jsonb,
  $j$[{"path": "manual1123/w3/a649/em_pairs_649_draft1.json", "md5": "1a2e03af69f6a5dfee80be6fda3be3ef", "what": "the two old and new texts written (commit b721a106 by Wall 12055)"}]$j$::jsonb,
  $j${"engine_manual": "parts are versioned and rows are kept; part 11.0 version 326 stands as its own row. Undo is a new version of part 11.0 holding the old text, on the operator's word.", "engine": "not written; nothing to revert", "rehearsed": "the two replacements were previewed on version 318 by W3 and reproduced by W1 (Wall 12056) before the card, and previewed again on version 326 inside the write call", "source": "W3's write call; Wall 12056"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (pairs draft 1, file md5 1a2e03af; preview on version 318: 38,138 characters, the md5 given here)", "wall_id": 12056, "md5_graded": "81093c11dc5c0809a4d1dfacaa586c7f", "verdict_norm": "PASS", "source": "Wall 12056"}, {"seat": "W1", "verdict": "PASS (READBACK AFTER THE WRITE, not a grade before it: W1 computed in SQL that version 327 equals version 326 with the two graded pairs applied; 37,420 characters, the md5 given here)", "wall_id": 12074, "md5_graded": "a631296d6a85652ca539ed74282a6850", "verdict_norm": "PASS", "source": "Wall 12074"}]$j$::jsonb,
  ARRAY['a631296d6a85652ca539ed74282a6850'], '[42225]'::jsonb,
  $j$[{"kind": "table row", "name": "engine manual part 11.0", "before": "version 326, md5 db2c50ca60851ad3db8fbadef563652f, 37,390 characters", "after": "version 327, md5 a631296d6a85652ca539ed74282a6850, 37,420 characters (+30); engine_manual_log row 347"}]$j$::jsonb,
  $j$[{"name": "Preview of the two replacements on version 318", "result": "each old text found once; result 38,138 characters, md5 81093c11; reproduced by W1", "source": "Wall 12055, 12056"}, {"name": "Preview again on version 326, inside the write call", "result": "each old text found once; length 37,420 checked; written on the preview md5 a631296d", "source": "W3's write call; Wall 12073"}, {"name": "Live dash_debaters()", "result": "12 rows matching pair 1 in order, haiku absent (W3's SQL; W1)", "source": "Wall 12055, 12056"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS: 11.0 version 327, 37,420 characters, md5 a631296d, equal to version 326 with the two graded 649 pairs applied (computed in SQL). NOT CHECKED: audit rows.", "wall_id": 12074, "source": "Wall 12074 (commit 8b7cc1bf)"}]$j$::jsonb,
  $j${"case": "NOT APPLICABLE: a manual correction; no engine behaviour changed.", "runs": [], "mark_for_the_next_run": "none", "not_shown": "the dashboard page itself was not loaded.", "source": "Wall 12055"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "WRITTEN: part 11.0 version 327, md5 a631296d6a85652ca539ed74282a6850, 37,420 characters, log row 347, audit 42225 (this row's own change)."}$j$::jsonb,
